    textureSample(u_modVCanvas, modvGroupSampler, vec2<f32>(xy1.x, xy2.y)) +
    textureSample(u_modVCanvas, modvGroupSampler, vec2<f32>(xy2.x, xy1.y))) / 4.0).rgb;
